package com.oms.supplychain;

import com.oms.supplychain.service.wms.*;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import com.ruoyi.common.core.domain.R;
import java.util.*;
import static com.oms.supplychain.PurchaseWorkspaceTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class WarehouseFullReconciliationTest {
 WarehouseControlTest fixture;WarehouseFullReconciliation full;WarehouseReconciliationGate gate;WarehouseReconciliation query;
 @BeforeAll static void start(){PurchaseWorkspaceTest.init();}
 @AfterAll static void stop(){PurchaseWorkspaceTest.shutdown();}
 @BeforeEach void setup(){fixture=new WarehouseControlTest();fixture.setup();db.update("DELETE FROM warehouse_reconciliation_result");db.update("DELETE FROM warehouse_reconciliation_gate");
  long connection=context.getBean(WmsConnections.class).save("QM",m("name","TEST全仓","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://localhost/qimen","app_key","APP","customer_id","OWNER","secret","SECRET","enabled",1));db.update("UPDATE wms_simulation_store_info SET connection_id=?,external_owner='O',external_warehouse='W' WHERE company_key='QM' AND wms_simulation_code='V'",connection);
  gate=new WarehouseReconciliationGate();set(gate,"db",context.getBean(WmsStore.class));set(gate,"scope",fixture.scope);full=new WarehouseFullReconciliation();set(full,"db",context.getBean(WmsStore.class));set(full,"scope",fixture.scope);set(full,"stock",fixture.stock);set(full,"gate",gate);set(full,"work",mock(WarehouseControlWork.class));query=mock(WarehouseReconciliation.class);set(full,"reconciliation",query);set(fixture.service,"full",full);set(fixture.service,"gate",gate);
  when(fixture.stock.execute(eq("QM"),eq("discover"),anyMap())).thenReturn(R.ok(m("rows",Arrays.asList(m("id",1,"sku_sn","A"),m("id",2,"sku_sn","A"),m("id",3,"sku_sn","000B")),"maximum",3,"cursor",3,"done",true)));
  doAnswer(inv->{long id=inv.getArgument(1);((Runnable)inv.getArgument(2)).run();String sku=db.queryForObject("SELECT item_sku FROM warehouse_reconciliation WHERE id=?",String.class,id);Map<String,Object>r=m("rows",Collections.singletonList(m("sku_sn",sku,"status","MATCHED","difference",0,"oms_physical",0,"wms_physical",0,"sources",Collections.emptyList())),"pending_documents",Collections.emptyList());db.update("UPDATE warehouse_reconciliation SET state='COMPLETED',result_json=? WHERE id=?",context.getBean(WmsStore.class).encode(r),id);return null;}).when(query).processItem(eq("QM"),anyLong(),any(Runnable.class));
 }
 void set(Object o,String field,Object value){ReflectionTestUtils.setField(o,field,value);}
 Map<String,Object>command(){return m("scope_mode","FULL","request_key","FULL_TEST","store_code","V");}
 long create(){return full.create("QM",command(),"tester");}
 Map<String,Object>head(long id){return db.queryForMap("SELECT * FROM warehouse_reconciliation WHERE id=?",id);}
 void finish(long id){for(int i=0;i<20&&Arrays.asList("PENDING","RUNNING","STOPPING").contains(head(id).get("state"));i++)full.process("QM",id);}
 @Test void createIsAsyncAndIdempotentWithoutStockOrWarehouseCalls(){long id=create();assertEquals(id,create());assertEquals("PENDING",head(id).get("state"));verifyNoInteractions(fixture.stock);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE parent_id=?",Integer.class,id));}
 @Test void fullCensusDeduplicatesVirtualRowsAndPreservesLeadingZeroSku(){long id=create();finish(id);assertEquals("COMPLETED",head(id).get("state"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE parent_id=?",Integer.class,id));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE parent_id=? AND item_sku='000B'",Integer.class,id));assertEquals(2L,full.results("QM",id,Collections.emptyMap()).get("total"));assertEquals(1L,fixture.service.list("QM",Collections.emptyMap()).get("total"));}
 @Test void resultsProjectionIsIdempotentAndTenantBound(){long id=create();finish(id);full.process("QM",id);assertEquals(2L,full.results("QM",id,Collections.emptyMap()).get("total"));assertThrows(IllegalArgumentException.class,()->full.results("OTHER",id,Collections.emptyMap()));}
 @Test void completeWarehouseManifestAddsWarehouseOnlySkuWithExplicitCoverage(){Map<String,Object>cmd=command();cmd.putAll(m("warehouse_skus",Arrays.asList("A","WMS_ONLY"),"warehouse_list_confirmed",true,"warehouse_list_evidence","仓库完整导出2026-10-27"));long id=full.create("QM",cmd,"tester");finish(id);assertEquals("OMS_WMS_LIST",head(id).get("coverage"));assertEquals(3L,full.results("QM",id,Collections.emptyMap()).get("total"));}
 @Test void incompleteUnconfirmedWarehouseListCannotClaimDualCoverage(){Map<String,Object>cmd=command();cmd.put("warehouse_skus",Collections.singletonList("A"));assertThrows(IllegalArgumentException.class,()->full.create("QM",cmd,"tester"));}
 @Test void failedSkuKeepsUnknownQuantityAndOnlyFailedIsRetried(){long id=create();doAnswer(inv->{long child=inv.getArgument(1);db.update("UPDATE warehouse_reconciliation SET state='FAILED',last_error='第2页未完整返回' WHERE id=?",child);return null;}).when(query).processItem(eq("QM"),anyLong(),any(Runnable.class));finish(id);assertEquals("PARTIAL",head(id).get("state"));Map<String,Object>row=fixture.scope.rows(full.results("QM",id,Collections.emptyMap()).get("rows")).get(0);assertEquals("QUERY_FAILED",row.get("status"));assertNull(row.get("wms_physical"));full.control("QM",id,"retryFailed","tester");assertEquals(0L,full.results("QM",id,Collections.emptyMap()).get("total"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE parent_id=? AND state='PENDING'",Integer.class,id));}
 @Test void stopBeforeFirstItemThenResumeKeepsOriginalTask(){long id=create();full.control("QM",id,"stop","tester");full.process("QM",id);assertEquals("STOPPED",head(id).get("state"));verifyNoInteractions(fixture.stock);full.control("QM",id,"resume","tester");finish(id);assertEquals("COMPLETED",head(id).get("state"));}
 @Test void workerIsBoundedToFiveSkuQueriesAndSuccessfulEvidenceSurvivesResume(){List<Map<String,Object>>skus=new ArrayList<>();for(int i=0;i<12;i++)skus.add(m("id",i+1,"sku_sn","S"+i));when(fixture.stock.execute(eq("QM"),eq("discover"),anyMap())).thenReturn(R.ok(m("rows",skus,"cursor",12,"maximum",12,"done",true)));long id=create();full.process("QM",id);verify(query,times(5)).processItem(eq("QM"),anyLong(),any(Runnable.class));full.control("QM",id,"stop","tester");full.process("QM",id);assertEquals(5L,full.results("QM",id,Collections.emptyMap()).get("total"));full.control("QM",id,"resume","tester");finish(id);assertEquals(13L,full.results("QM",id,Collections.emptyMap()).get("total"));verify(query,times(13)).processItem(eq("QM"),anyLong(),any(Runnable.class));}
 @Test void sameWarehouseGatePreventsConcurrentQueriesAndStaleOwnerCannotRenew(){long id=create();Map<String,Object>d=head(id);assertTrue(gate.acquire("QM",d,"ONE"));assertFalse(gate.acquire("QM",d,"TWO"));assertThrows(IllegalArgumentException.class,()->gate.renew("QM",d,"TWO"));full.process("QM",id);verifyNoInteractions(fixture.stock);gate.release("QM",d,"ONE");finish(id);assertEquals("COMPLETED",head(id).get("state"));}
 @Test void fullTaskNeverAllowsDirectInventoryAdjustment(){long id=create();finish(id);assertThrows(IllegalArgumentException.class,()->fixture.service.adjustment("QM",id,Collections.emptyMap(),"tester"));verify(fixture.stock,never()).execute(anyString(),eq("adjust"),anyMap());}
 @Test void resultFilterAndPagingDoNotReturnWholeWarehouse(){long id=create();finish(id);assertEquals(0L,full.results("QM",id,Collections.singletonMap("status","ABNORMAL")).get("total"));assertEquals(1,fixture.scope.rows(full.results("QM",id,Collections.singletonMap("pageSize","1")).get("rows")).size());assertEquals(1L,full.results("QM",id,Collections.singletonMap("sku_sn","000B")).get("total"));}
 @Test void recoveryScannerExcludesChildren(){long id=create();full.process("QM",id);reset((WarehouseControlWork)ReflectionTestUtils.getField(fixture.service,"work"));assertEquals(1,fixture.service.scan("QM"));verify((WarehouseControlWork)ReflectionTestUtils.getField(fixture.service,"work"),times(1)).ready("QM",id,false);}
 @Test void filteredCsvExportPreservesSkuAndNeverWritesInventory()throws Exception{long id=create();finish(id);java.io.StringWriter out=new java.io.StringWriter();full.export("QM",id,Collections.singletonMap("sku_sn","000B"),out);assertTrue(out.toString().contains("'000B"));assertFalse(out.toString().contains("\"'A\""));assertEquals(2L,((Number)head(id).get("successful_count")).longValue());assertEquals(2L,((Number)head(id).get("discovered_count")).longValue());verify(fixture.stock,never()).execute(anyString(),eq("adjust"),anyMap());}

 @Test void childCannotBeRetriedOutsideItsParentScheduler(){long id=create();finish(id);long child=db.queryForObject("SELECT MIN(id) FROM warehouse_reconciliation WHERE parent_id=?",Long.class,id);db.update("UPDATE warehouse_reconciliation SET state='FAILED' WHERE id=?",child);assertThrows(IllegalArgumentException.class,()->fixture.service.retry("QM",child));assertEquals("FAILED",head(child).get("state"));verify(fixture.stock,never()).execute(anyString(),eq("adjust"),anyMap());}

 @Test void emptyFilteredExportFlushesTheCsvHeaderWithoutAnExtraCallerFlush()throws Exception{long id=create();finish(id);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();full.export("QM",id,Collections.singletonMap("status","QUERY_FAILED"),new java.io.OutputStreamWriter(bytes,java.nio.charset.StandardCharsets.UTF_8));assertTrue(new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8).startsWith("SKU,"));}

}
